/**
 * 测试替身：`@deepseek-ai/dsh-tools` 的最小可用子集。
 *
 * 为什么需要它：真实包由 DSH 的「运行时解析」在宿主进程内提供，**在宿主之外**
 * （例如 `node --test` 直接跑）解析不到。接线回归测试要断言的只是**接线**
 * （`ctx.inject` 是否正确启动子插件、两个面是否各自注册），不该取决于本机装没装
 * 过哪个 dsh。
 *
 * 纪律：替身必须**比真实更严格**——真实 `defineTool` 会做的
 * 校验这里都要复刻，只复刻接口形状等于没测。本文件复刻的真实校验：
 *   ① `name` / `description` 为无空白非空字符串；
 *   ② `timeoutMs` 缺省可省，给出时必须是正有限数；
 *   ③ `parameters` 是「名字 → schema 对象」的映射；`required` 只允许 `true`
 *      （实测 `required:false` 会被真实实现以 unsupported JSON schema 拒绝）；
 *   ④ `output` 必填且为对象，`output.schema` 为对象，**`output.render` 必须是函数**
 *      （漏了它真实运行时报 `output.render failed: userRender is not a function`）。
 *
 * 它不做执行、不碰网络、不落盘。
 */

/** 与真实实现同名的错误类型，便于上层按类型分辨。 */
export class JsonSchemaError extends Error {}

/** 缺省参数对象：真实实现允许 `parameters` 省略。 */
function assertParameterMap(name, parameters) {
  if (typeof parameters !== 'object' || parameters === null || Array.isArray(parameters)) {
    throw new JsonSchemaError(`defineTool(${name}): parameters must be an object mapping names to schemas`);
  }
  for (const [key, spec] of Object.entries(parameters)) {
    if (typeof spec !== 'object' || spec === null || Array.isArray(spec)) {
      throw new JsonSchemaError(`defineTool(${name}): parameters.${key} must be a schema object`);
    }
    if (typeof spec.type !== 'string' || spec.type === '') {
      throw new JsonSchemaError(`defineTool(${name}): parameters.${key}.type must be a non-empty string`);
    }
    if ('required' in spec && spec.required !== true) {
      throw new JsonSchemaError(
        `defineTool(${name}): unsupported JSON schema at parameters.${key}.required — 必填由「不写 required」表达，写 required:false 会被拒绝`,
      );
    }
  }
}

/** 输出契约：`schema` + 必填 `render`。 */
function assertOutput(name, output) {
  if (typeof output !== 'object' || output === null || Array.isArray(output)) {
    throw new JsonSchemaError(`defineTool(${name}): output is required and must be an object`);
  }
  if (typeof output.schema !== 'object' || output.schema === null || Array.isArray(output.schema)) {
    throw new JsonSchemaError(`defineTool(${name}): output.schema must be an object (not a bare schema)`);
  }
  if (typeof output.render !== 'function') {
    throw new JsonSchemaError(`defineTool(${name}): output.render is required`);
  }
}

/**
 * 复刻真实 `defineTool` 的校验并返回定义本身。
 * @param {object} options 工具定义
 * @returns {object} 同一个定义对象（浅拷贝）
 */
export function defineTool(options) {
  if (typeof options !== 'object' || options === null || Array.isArray(options)) {
    throw new TypeError('defineTool: options must be an object');
  }
  const { name } = options;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('defineTool: name must be a non-empty string');
  }
  if (typeof options.description !== 'string' || options.description.trim() === '') {
    throw new TypeError(`defineTool(${name}): description must be a non-empty string`);
  }
  if (options.timeoutMs !== undefined && (!Number.isFinite(options.timeoutMs) || options.timeoutMs <= 0)) {
    throw new Error(`defineTool(${name}): timeoutMs must be a positive finite number`);
  }
  if (options.parameters !== undefined) assertParameterMap(name, options.parameters);
  assertOutput(name, options.output);
  if (typeof options.execute !== 'function') {
    throw new TypeError(`defineTool(${name}): execute must be a function`);
  }
  return { ...options };
}

export default { defineTool };
